-- 2026-11-14 收录第一批外部网页游戏（只插入，不改已有行）。
-- Slow Roads、shapez、信任的进化、HexGL、Sandspiel、Line Rider、猫国建设者为 embed；
-- Die in the Dungeon CLASSIC、Dragonsweeper、Sort the Court! 为 itch 原页，只能 link。
-- INSERT OR IGNORE：若本地先导入了含这 10 条的 jiwan.sql，本迁移不会覆盖已有数据。

INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('slow-roads', '慢路', 'Slow Roads', 'manlu slow roads man lu', 'Anslo / Topograph Interactive', '', '', NULL, '', 0, 2022, 'action', '["驾驶","放松","3D"]', 30, 0.08, 'io', 'https://slowroads.io/', 0, 0, 0, 1, 1, 0, 1, 'mid', 'hosted', '路没有尽头，风景会一直变', '在程序生成的风景公路上一直开下去。', 'An endless drive through a generated landscape.', '由 Topograph Interactive 的 Anslo 制作，并以 CC BY-NC-ND 4.0 授权。网页版由作者在 slowroads.io 免费提供，画面和内容均属原作，不是即玩的作品。在即玩里直接打开原作；请勿镜像或改编。另有 Steam 完整版。', 'Made by Anslo of Topograph Interactive and released under CC BY-NC-ND 4.0. The free web edition is provided by the author at slowroads.io; the work is not Jiwan’s. It opens here in the original page. Do not mirror or adapt it. A full edition is also on Steam.', 'assets/posters/slow-roads.jpg', 1280, 800, 'center', '["assets/posters/slow-roads.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -10, 1794656400000, 'The road has no end. The landscape keeps changing.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('shapez', 'shapez', 'shapez', 'shapez yixinggongchang 异形工厂', 'tobspr Games', '', '', NULL, '', 0, 2020, 'puzzle', '["工厂","建造","益智"]', 150, 0.08, 'io', 'https://shapez.io/', 0, 0, 0, 1, 1, 0, 1, 'long', 'hosted', '把一块图形做成一座工厂', '切开、旋转、合并、涂色，搭一条自动化生产线。这是官方网页试玩版。', 'Cut, rotate, merge and paint shapes into an automated factory. Official web demo.', '由 tobspr Games 制作，源码以 GPL-3.0 发布。这是官方在 shapez.io 提供的网页试玩，完整版在 Steam，不是即玩的作品。在即玩里直接打开原作。用 Steam 登录只为在浏览器里解锁完整版，试玩不用登录。', 'Made by tobspr Games; the source is GPL-3.0. This is the official web demo at shapez.io (the full game is on Steam), not a Jiwan original. It opens here. Steam sign-in is only for unlocking the full version in the browser; the demo needs no login.', 'assets/posters/shapez.jpg', 1280, 800, 'center', '["assets/posters/shapez.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -9, 1794656400000, 'Turn one shape into a factory.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('evolution-of-trust', '信任的进化', 'The Evolution of Trust', 'xinren de jinhua trust evolution xinrenjinhua', 'Nicky Case', '', '', NULL, '', 0, 2017, 'story', '["互动叙事","益智","科普"]', 0, 0.02, 'story', 'https://ncase.me/trust/', 0, 0, 0, 1, 1, 0, 1, 'mid', 'hosted', '信任是怎么来的，又怎么没的', '用一小局一小局博弈，把「信任」怎样形成、破裂讲清楚。大约三十分钟。', 'A thirty-minute explorable guide to how trust forms and falls apart.', '由 Nicky Case 制作，以 CC0 1.0 贡献到公共领域。原页托管在 ncase.me/trust，不是即玩的作品。在即玩里直接打开原作。作者页列出了粉丝中文译本（繁中：https://audreyt.github.io/trust-zh-TW/）。', 'Made by Nicky Case and released under CC0 1.0. Hosted at ncase.me/trust; it is not a Jiwan original. It opens here. Fan translations, including Traditional Chinese, are listed on the author’s page (https://audreyt.github.io/trust-zh-TW/).', 'assets/posters/evolution-of-trust.jpg', 1280, 800, 'center', '["assets/posters/evolution-of-trust.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -8, 1794656400000, 'How trust is built, and how it breaks.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('die-in-the-dungeon', 'Die in the Dungeon CLASSIC', 'Die in the Dungeon CLASSIC', 'die in the dungeon classic ditd roguelike shaizi', 'Alarts, SexyBuggy, Jaun', '', '', NULL, '', 0, 2021, 'action', '["肉鸽","回合制","骰子"]', 110, 0.12, 'io', 'https://alarts.itch.io/die-in-the-dungeon', 0, 0, 0, 1, 1, 0, 0, 'mid', '', '不发牌，只掷骰子下地牢', '用骰子组合过关的回合制肉鸽。网页是 Classic，完整版在 Steam。', 'A turn-based roguelite played with dice. The web version is Classic; the full game is on Steam.', '由 Alarts、SexyBuggy、Jaun 等制作。这是作者在 itch.io 免费提供的 Classic 网页版，不是即玩的作品。原作无法嵌进即玩，点「去原页玩 ↗」在新窗口打开作者页面。完整版在 Steam。', 'Made by Alarts, SexyBuggy, Jaun and collaborators. This is the free Classic web edition on itch.io, not a Jiwan original. It cannot be embedded here; use “Play on original ↗” to open the author’s page. The full game is on Steam.', 'assets/posters/die-in-the-dungeon.png', 935, 567, 'center', '["assets/posters/die-in-the-dungeon.png"]', '[[935,567]]', '[0,0,0,0,0]', -7, 1794656400000, 'No cards. Just dice, down the dungeon.', '', '', 0);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('dragonsweeper', 'Dragonsweeper', 'Dragonsweeper', 'dragonsweeper saolei long saolei', 'Daniel Benmergui', '', '', NULL, '', 0, 2025, 'puzzle', '["益智","扫雷","Roguelike"]', 200, 0.04, 'story', 'https://danielben.itch.io/dragonsweeper', 0, 0, 0, 1, 0, 0, 0, 'mid', '', '先读怪物图鉴，再翻那一格', '扫雷和地下城探索混在一起，对照图鉴判断格子。', 'Minesweeper mixed with a dungeon crawl. Use the bestiary to read the board.', '由 Daniel Benmergui 制作，在 itch.io 免费提供。这是作者的原作，不是即玩的作品。原作无法嵌进即玩，点「去原页玩 ↗」在新窗口打开作者页面。', 'Made by Daniel Benmergui and offered for free on itch.io. It is not a Jiwan original. It cannot be embedded here; use “Play on original ↗” to open the author’s page.', 'assets/posters/dragonsweeper.jpg', 894, 780, 'center', '["assets/posters/dragonsweeper.jpg"]', '[[894,780]]', '[0,0,0,0,0]', -6, 1794656400000, 'Read the monsternomicon, then uncover a tile.', '', '', 0);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('hexgl', 'HexGL', 'HexGL', 'hexgl webgl saiche hex gl', 'Thibaut Despoulain', 'BKcore', '', NULL, '', 0, 2012, 'action', '["竞速","3D","WebGL"]', 20, 0.14, 'io', 'https://hexgl.bkcore.com/play/', 0, 0, 0, 1, 1, 0, 1, 'short', 'hosted', '在光轨上把船开出去', '经典 WebGL 未来科幻赛车，键盘就能开跑。', 'A classic futuristic WebGL racer you can play with the keyboard.', '由 Thibaut Despoulain（BKcore）制作，以 MIT 许可开源。原页托管在 hexgl.bkcore.com，不是即玩的作品。在即玩里直接打开原作。', 'Made by Thibaut Despoulain (BKcore) and released under the MIT license. Hosted at hexgl.bkcore.com; it is not a Jiwan original. It opens here.', 'assets/posters/hexgl.jpg', 1280, 800, 'center', '["assets/posters/hexgl.jpg"]', '[[1280,800]]', '[0,0,0,0,0]', -5, 1794656400000, 'Take the ship out on a track of light.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('sandspiel', 'Sandspiel', 'Sandspiel', 'sandspiel shahua shazi sand spiel', 'Max Bittker', '', '', NULL, '', 0, 2018, 'puzzle', '["沙盒","创意","模拟"]', 25, 0.08, 'io', 'https://sandspiel.club/', 0, 0, 0, 1, 0, 0, 0, 'short', 'hosted', '倒下沙子，看它自己长', '在画布上倒沙子、水、火和植物，看它们互相反应。', 'Pour sand, water, fire and plants on a canvas and watch them interact.', '由 Max Bittker 制作，以 MIT 许可开源。原页托管在 sandspiel.club，不是即玩的作品。在即玩里直接打开原作。原页可能带广告和 Cookie 提示。', 'Made by Max Bittker and released under the MIT license. Hosted at sandspiel.club; it is not a Jiwan original. It opens here. The original page may show ads and a cookie notice.', 'assets/posters/sandspiel.jpg', 1012, 748, 'center', '["assets/posters/sandspiel.jpg"]', '[[1012,748]]', '[0,0,0,0,0]', -4, 1794656400000, 'Pour the sand and watch it grow.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('linerider', 'Line Rider', 'Line Rider', 'line rider huaxue xueqiao linerider', 'Boštjan Čadež', '', '', NULL, '', 0, 2006, 'puzzle', '["沙盒","绘画","物理"]', 0, 0.02, 'io', 'https://www.linerider.com/', 0, 0, 0, 1, 0, 0, 0, 'short', 'hosted', '你画线，雪橇自己滑下去', '自己画赛道，小人坐雪橇顺着线滑下去。', 'Draw a track and watch the sledder ride the line you made.', '由 Boštjan Čadež 制作。「Line Rider」是 Boštjan Čadež 的注册商标，版权归原作者所有，不是即玩的作品。这是官方网站 linerider.com 提供的免费网页版。在即玩里直接打开原作。', 'Made by Boštjan Čadež. “Line Rider” is a registered trademark of Boštjan Čadež; the work is not Jiwan’s. This is the free official web edition at linerider.com. It opens here.', 'assets/posters/linerider.jpg', 675, 413, 'center', '["assets/posters/linerider.jpg"]', '[[675,413]]', '[0,0,0,0,0]', -3, 1794656400000, 'You draw the line. The sled takes it from there.', '', '', 1);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('sort-the-court', 'Sort the Court!', 'Sort the Court!', 'sort the court gongting caijue yes no', 'Graeme Borland', '', '', NULL, '', 0, 2016, 'story', '["模拟","决策","像素"]', 25, 0.12, 'story', 'https://graebor.itch.io/sort-the-court', 0, 0, 0, 1, 0, 0, 0, 'short', '', '只答是或否，王国就会变', '对来访的人只答「是」或「否」，看小王国被你判成什么样。', 'Answer visitors with yes or no and watch what becomes of the kingdom.', '程序由 Graeme Borland 制作，美术 @amymja，音乐 @bogdan_rybak。作者在 itch.io 免费提供网页版，不是即玩的作品。原作无法嵌进即玩，点「去原页玩 ↗」在新窗口打开作者页面。更新的手机/多语言版在 Poki。', 'Code by Graeme Borland, art by @amymja, music by @bogdan_rybak. The free web edition is on itch.io and is not a Jiwan original. It cannot be embedded here; use “Play on original ↗” to open the author’s page. An updated mobile and multilingual version is on Poki.', 'assets/posters/sort-the-court.png', 945, 539, 'center', '["assets/posters/sort-the-court.png"]', '[[945,539]]', '[0,0,0,0,0]', -2, 1794656400000, 'Answer yes or no, and the kingdom changes.', '', '', 0);
INSERT OR IGNORE INTO games (id, title, title_en, pinyin, author, maker, source, score, players, plays, year, cat, tags, hue, chroma, play, src, demo, fable, hot, neu, featured, pick, wide, duration, origin, banner, blurb, blurb_en, about, about_en, poster, pw, ph, pos, shots, shotSize, dist, ord, at, banner_en, packStatus, ownerId, embed) VALUES ('kittens-game', '猫国建设者', 'Kittens Game', 'maoguojianshezhe maoguo kittens game maohehe maoninghe', 'bloodrizer', '', '', NULL, '', 0, 2014, 'idle', '["放置","经营","策略"]', 0, 0.06, 'clicker', 'https://kittensgame.com/web/', 0, 0, 0, 1, 0, 0, 1, 'long', 'hosted', '从一株猫薄荷开始建国', '从采集猫薄荷开始的重度放置经营。官方网页已有中文。', 'A deep idle empire that starts with gathering catnip. The official site is in Chinese too.', '由 bloodrizer 制作。这是官方在 kittensgame.com 提供的免费网页版，不是即玩的作品。在即玩里直接打开原作。右上角登录只用于可选的云存档，开玩不用登录。另有 Steam 与手机版。', 'Made by bloodrizer. This is the free official web edition at kittensgame.com, not a Jiwan original. It opens here. The sign-in control is only for optional cloud saves; you can play without an account. Steam and mobile editions also exist.', 'assets/posters/kittens-game.jpg', 1280, 400, 'center', '["assets/posters/kittens-game.jpg"]', '[[1280,400]]', '[0,0,0,0,0]', -1, 1794656400000, 'Found a nation with one sprig of catnip.', '', '', 1);
